import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    totals = {}
    for i in range(n):
        name = data[1 + 2 * i]
        amount = int(data[2 + 2 * i])
        totals[name] = totals.get(name, 0) + amount
    for name in sorted(totals):
        print(name, totals[name])

main()
